```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Test fixtures - properly organized, as one would expect
const mockCartItems = [
  { id: '1', name: 'Surgical Scalpel', price: 49.99 },
  { id: '2', name: 'Medical Journal', price: 129.00 }
];

const validShipping = {
  street: '123 Beacon Hill',
  city: 'Boston',
  state: 'MA',
  zip: '02108'
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'Charles E Winchester III'
};

describe('Checkout Component', () => {
  let mockProcessPayment: ReturnType<typeof vi.fn>;
  let mockClearCart: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    mockProcessPayment = vi.fn().mockResolvedValue({ orderId: 'ORD-12345' });
    mockClearCart = vi.fn();
  });

  const renderCheckout = (cartItems = mockCartItems) => {
    return render(
      <CartProvider items={cartItems} clearCart={mockClearCart}>
        <PaymentProvider processPayment={mockProcessPayment}>
          <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
        </PaymentProvider>
      </CartProvider>
    );
  };

  describe('Happy Path - Complete Checkout Flow', () => {
    it('completes full checkout from shipping to confirmation', async () => {
      const user = userEvent.setup();
      renderCheckout();

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), validShipping.street);
      await user.type(screen.getByLabelText(/city/i), validShipping.city);
      await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
      await user.type(screen.getByLabelText(/zip/i), validShipping.zip);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
      await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
      await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
      await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByRole('region', { name: /order review/i })).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText('ORD-12345')).toBeInTheDocument();
    });
  });

  describe('Form Validation', () => {
    it('displays error when ZIP code format is invalid', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip/i), 'INVALID');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code/i);
    });

    it('displays error for invalid card number', async () => {
      const user = userEvent.setup();
      renderCheckout();
      // Navigate to payment...

      await user.type(screen.getByLabelText(/card number/i), '1234');
      await user.click(screen.getByRole('button', { name: /review/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/16-digit/i);
    });
  });

  describe('Edge Cases', () => {
    it('displays empty cart message when no items', () => {
      renderCheckout([]);
      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });

    it('handles payment failure gracefully', async () => {
      mockProcessPayment.mockRejectedValue(new Error('Card declined'));
      // Complete to review step, then place order...

      expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);
    });
  });

  describe('Accessibility', () => {
    it('has no accessibility violations', async () => {
      const { container } = renderCheckout();
      expect(await axe(container)).toHaveNoViolations();
    });
  });
});
